text:
{
  "name": "gpt-ziikoo-void",
  "workers_dev": false,
  "preview_urls": false,
  "routes": [
    {
      "pattern": "gpt.ziikoo.app",
      "custom_domain": true
    }
  ],
  "ratelimits": [
    {
      "name": "IP_LIMITER",
      "namespace_id": "7101",
      "simple": {
        "limit": 150,
        "period": 60
      }
    },
    {
      "name": "HOST_LIMITER",
      "namespace_id": "7102",
      "simple": {
        "limit": 120,
        "period": 60
      }
    }
  ],
  "observability": {
    "enabled": true,
    "logs": {
      "enabled": true,
      "invocation_logs": false,
      "head_sampling_rate": 1
    }
  },
  "durable_objects": {
    "bindings": [
      {
        "name": "BOARD",
        "class_name": "BoardDurableObject"
      },
      {
        "name": "TARGET",
        "class_name": "TargetDurableObject"
      },
      {
        "name": "WATCH_REGISTRY",
        "class_name": "WatchRegistryDurableObject"
      },
      {
        "name": "WATCH",
        "class_name": "WatchDurableObject"
      }
    ]
  },
  "migrations": [
    {
      "tag": "void-durable-board-v1",
      "new_sqlite_classes": [
        "BoardDurableObject"
      ]
    },
    {
      "tag": "void-durable-target-v1",
      "new_sqlite_classes": [
        "TargetDurableObject"
      ]
    },
    {
      "tag": "void-durable-watch-registry-v1",
      "new_sqlite_classes": [
        "WatchRegistryDurableObject"
      ]
    },
    {
      "tag": "void-durable-watch-v1",
      "new_sqlite_classes": [
        "WatchDurableObject"
      ]
    }
  ],
  "account_id": "d1da4742bef1158b96eb2a2660a49301",
  "compatibility_date": "2026-02-24",
  "d1_databases": [
    {
      "binding": "DB",
      "database_name": "gpt-ziikoo-void-db",
      "database_id": "8b80053c-69c8-4a11-b23d-eb9a8af07d8d",
      "migrations_dir": "./db/migrations"
    }
  ],
  "send_email": [
    {
      "name": "SEND_EMAIL"
    }
  ],
  "vars": {
    "__VOID_EMAIL_FROM": "alerts@mail.gpt.ziikoo.app"
  },
  "addresses": [
    "w@mail.gpt.ziikoo.app"
  ]
}
